{
  "table": {
    "name": "customer_monthly_spend",
    "purpose": "Aggregated spending per customer per month (YYYYMM), likely derived from the transactions tables; col_003 is the total amount spent by that customer in that month, with negative values indicating refunds/credits."
  },
  "columns": {
    "col_001": {
      "role": "foreign_key",
      "name": "customer_id",
      "description": "Identifier of the customer; references customers.col_001 (many-to-one). Each customer appears in many rows (one per month).",
      "status": "resolved"
    },
    "col_002": {
      "role": "date",
      "name": "year_month",
      "description": "Month identifier in YYYYMM format (values 201112 through 201311, i.e. Dec 2011 to Nov 2013). Stored as VARCHAR but numeric.",
      "status": "resolved"
    },
    "col_003": {
      "role": "numeric",
      "name": "total_spend",
      "description": "Total amount spent by the customer in that month (currency, likely euros given the gas-station context). Mostly positive; negative values (min -582092.86) suggest refunds, reversals or credit adjustments. Tentative: could be a balance/loyalty-points amount instead of spend, but the distribution and transaction context support a monthly spend total.",
      "status": "tentative"
    }
  }
}
